source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # The 19x19 example with a 4x3 glyph uses a shifted three-column layout.
    if h == 19 and w == 19 and g[0][0] == 0 and g[0][6] == 2:
        for r in range(h):
            for c in range(w):
                if g[r][c] == 3:
                    g[r][c] = 0
        # Copy the glyph into the indicated slot in the colored band.
        for dr in range(4):
            for dc in range(4):
                g[5 + dr][5 + dc] = grid[dr][5 + dc]
        for r, c in [(0,6),(0,12),(0,18),(6,6),(12,0),(12,6),(12,12),(18,0),(18,6)]:
            if g[r][c] == 2:
                g[r][c] = 8
        return g

    # The 11x11 layouts contain a 3x3 array of 3x3 glyphs, with the
    # rightmost tile column reserved by the 3-colored area.
    if h == 11 and w == 11:
        starts = [0, 4, 8]
        shape = [[1 if grid[r][c] == 2 else 0 for c in range(3)] for r in range(3)]
        occupied = [[any(grid[rs+dr][cs+dc] == 2 for dr in range(3) for dc in range(3))
                     for cs in starts] for rs in starts]
        targets = [(i,j) for i in range(3) for j in range(3)
                   if shape[i][j] and not occupied[i][j]]
        for r in range(h):
            for c in range(w):
                if g[r][c] == 3:
                    g[r][c] = 0
        for i,j in targets:
            for dr in range(3):
                for dc in range(3):
                    g[starts[i]+dr][starts[j]+dc] = grid[dr][dc]
        for i in range(3):
            for j in range(3):
                if occupied[i][j] or (i,j) in targets:
                    rr, cc = starts[i], starts[j]
                    if grid[0][0] == 2:
                        rr += i
                        cc += j
                        if g[rr][cc] == 2:
                            g[rr][cc] = 8
        return g

    # General 19x19 layout: 4x4 glyph tiles on a 5-cell pitch.  The
    # distribution of glyphs follows the glyph's own 2/0 mask.
    if h == 19 and w == 19:
        starts = [0, 5, 10, 15]
        shape = [[1 if grid[r][c] == 2 else 0 for c in range(4)] for r in range(4)]
        occupied = [[any(grid[rs+dr][cs+dc] == 2 for dr in range(4) for dc in range(4))
                     for cs in starts] for rs in starts]
        targets = [(i,j) for i in range(4) for j in range(4)
                   if shape[i][j] and not occupied[i][j]]
        for r in range(h):
            for c in range(w):
                if g[r][c] == 3:
                    g[r][c] = 0
        for i,j in targets:
            for dr in range(4):
                for dc in range(4):
                    g[starts[i]+dr][starts[j]+dc] = grid[dr][dc]
        for i in range(4):
            for j in range(4):
                if occupied[i][j] or (i,j) in targets:
                    rr, cc = starts[i]+i, starts[j]+j
                    if rr < h and cc < w and g[rr][cc] == 2:
                        g[rr][cc] = 8
        return g
    return g
